sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below

   if(!/^\d{4}$/.test(newValue)) {
		g_form.addErrorMessage("Invalid format for Release Year!");
		g_form.setValue("release_year", "");
   } else if (parseInt(newValue) < 1895 || parseInt(newValue) > new Date().getFullYear()) {
        g_form.addErrorMessage("Release Year must be between 1895 and " + new Date().getFullYear()+"!");
        g_form.setValue("release_year", "");
    }
	else {
		g_form.clearMessages();
	}

}
